<?php
/**
 * Image uploads.
 *
 * Nothing here trusts the browser. A file is accepted only if getimagesize()
 * agrees it is a real JPEG/PNG/WebP, the finfo MIME matches, and the extension
 * is on the allowlist. The stored filename is generated by us, never taken
 * from the upload — and /uploads has an .htaccess that refuses to execute
 * anything, so even a crafted file is inert.
 */
declare(strict_types=1);

const UPLOAD_MAX_BYTES = 6 * 1024 * 1024;   // 6 MB
const UPLOAD_SIZES     = [320, 640, 1200];  // responsive widths generated per image

function upload_error_text(int $code): string
{
    return match ($code) {
        UPLOAD_ERR_INI_SIZE, UPLOAD_ERR_FORM_SIZE => 'That file is too large.',
        UPLOAD_ERR_PARTIAL   => 'The upload was interrupted. Please try again.',
        UPLOAD_ERR_NO_FILE   => 'No file was chosen.',
        UPLOAD_ERR_NO_TMP_DIR, UPLOAD_ERR_CANT_WRITE => 'The server could not save the file.',
        default              => 'The upload failed.',
    };
}

/**
 * Validate and store one uploaded image.
 *
 * @param array  $file   one entry from $_FILES
 * @param string $subdir products | reviews | banners | blog | patterns
 * @return array{ok:bool, path?:string, error?:string}
 */
function upload_image(array $file, string $subdir = 'products'): array
{
    global $SITE;

    if (!isset($file['error']) || is_array($file['error'])) {
        return ['ok' => false, 'error' => 'Invalid upload.'];
    }
    if ($file['error'] !== UPLOAD_ERR_OK) {
        return ['ok' => false, 'error' => upload_error_text((int) $file['error'])];
    }
    if (($file['size'] ?? 0) > UPLOAD_MAX_BYTES) {
        return ['ok' => false, 'error' => 'Images must be under 6 MB. Try saving it smaller.'];
    }
    if (!is_uploaded_file($file['tmp_name'])) {
        return ['ok' => false, 'error' => 'Invalid upload.'];
    }

    // Is it genuinely an image, and which kind?
    $info = @getimagesize($file['tmp_name']);
    if ($info === false) {
        return ['ok' => false, 'error' => 'That file is not an image we can read.'];
    }

    $allowed = [
        IMAGETYPE_JPEG => ['jpg',  'image/jpeg'],
        IMAGETYPE_PNG  => ['png',  'image/png'],
        IMAGETYPE_WEBP => ['webp', 'image/webp'],
    ];
    $type = (int) $info[2];
    if (!isset($allowed[$type])) {
        return ['ok' => false, 'error' => 'Please upload a JPG, PNG or WebP.'];
    }
    [$ext, $expectMime] = $allowed[$type];

    // Second opinion from finfo — getimagesize alone can be fooled.
    if (class_exists('finfo')) {
        $mime = (new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);
        if ($mime !== $expectMime) {
            return ['ok' => false, 'error' => 'That file does not look like a real image.'];
        }
    }

    $subdir = preg_match('/^[a-z]+$/', $subdir) ? $subdir : 'products';
    $dir    = rtrim($SITE['upload_dir'], '/\\') . '/' . $subdir;

    if (!is_dir($dir) && !@mkdir($dir, 0755, true) && !is_dir($dir)) {
        return ['ok' => false, 'error' => 'Upload folder is not writable.'];
    }

    $base = date('Ymd') . '-' . bin2hex(random_bytes(6));

    // Always store JPEG. WebP is accepted as input, but many shared hosts
    // serve .webp as octet-stream; nosniff then blanks every image.
    $dest = $dir . '/' . $base . '.jpg';
    if ($type === IMAGETYPE_JPEG) {
        if (!move_uploaded_file($file['tmp_name'], $dest)) {
            return ['ok' => false, 'error' => 'Could not save the file.'];
        }
    } else {
        $img = $type === IMAGETYPE_PNG
            ? @imagecreatefrompng($file['tmp_name'])
            : @imagecreatefromwebp($file['tmp_name']);
        if (!$img) {
            return ['ok' => false, 'error' => 'That file is not an image we can read.'];
        }
        $w = imagesx($img);
        $h = imagesy($img);
        $out = imagecreatetruecolor($w, $h);
        $white = imagecolorallocate($out, 255, 255, 255);
        imagefilledrectangle($out, 0, 0, $w, $h, $white);
        imagecopy($out, $img, 0, 0, 0, 0, $w, $h);
        $ok = imagejpeg($out, $dest, 82);
        imagedestroy($out);
        imagedestroy($img);
        if (!$ok) {
            return ['ok' => false, 'error' => 'Could not save the file.'];
        }
    }
    @chmod($dest, 0644);

    // Responsive copies. Failure here is not fatal — the original still works.
    try {
        upload_make_sizes($dest, IMAGETYPE_JPEG, $dir, $base, 'jpg');
    } catch (Throwable $e) {
        error_log('Resize failed for ' . $dest . ': ' . $e->getMessage());
    }

    return ['ok' => true, 'path' => $subdir . '/' . $base . '.jpg'];
}

/** Generate 320/640/1200px versions alongside the original. */
function upload_make_sizes(string $src, int $type, string $dir, string $base, string $ext): void
{
    if (!function_exists('imagecreatetruecolor')) {
        return;
    }

    $img = match ($type) {
        IMAGETYPE_JPEG => @imagecreatefromjpeg($src),
        IMAGETYPE_PNG  => @imagecreatefrompng($src),
        IMAGETYPE_WEBP => @imagecreatefromwebp($src),
        default        => false,
    };
    if (!$img) {
        return;
    }

    $w = imagesx($img);
    $h = imagesy($img);

    foreach (UPLOAD_SIZES as $target) {
        if ($w <= $target) {
            continue;   // never upscale
        }
        $nh = (int) round($h * ($target / $w));
        $dst = imagecreatetruecolor($target, $nh);

        if ($type === IMAGETYPE_PNG || $type === IMAGETYPE_WEBP) {
            imagealphablending($dst, false);
            imagesavealpha($dst, true);
        }

        imagecopyresampled($dst, $img, 0, 0, 0, 0, $target, $nh, $w, $h);
        $out = $dir . '/' . $base . '-' . $target . '.' . $ext;

        match ($type) {
            IMAGETYPE_JPEG => imagejpeg($dst, $out, 82),
            IMAGETYPE_PNG  => imagepng($dst, $out, 6),
            IMAGETYPE_WEBP => imagewebp($dst, $out, 82),
            default        => null,
        };
        @chmod($out, 0644);
        imagedestroy($dst);
    }

    imagedestroy($img);
}

/** Delete an uploaded image and every generated size. */
function upload_delete(?string $path): void
{
    global $SITE;
    if (!$path) {
        return;
    }
    // Never let a stored path escape the uploads directory.
    if (str_contains($path, '..') || !preg_match('~^[a-z]+/[A-Za-z0-9\-]+\.(jpg|png|webp)$~', $path)) {
        return;
    }

    $full = rtrim($SITE['upload_dir'], '/\\') . '/' . $path;
    if (is_file($full)) {
        @unlink($full);
    }

    $dot = strrpos($full, '.');
    $stem = substr($full, 0, $dot);
    $ext  = substr($full, $dot);
    foreach (UPLOAD_SIZES as $s) {
        $sized = $stem . '-' . $s . $ext;
        if (is_file($sized)) {
            @unlink($sized);
        }
    }
}

/** srcset string for a stored image, when the generated sizes exist. */
function upload_srcset(?string $path): string
{
    global $SITE;
    if (!$path) {
        return '';
    }
    $dot  = strrpos($path, '.');
    $stem = substr($path, 0, $dot);
    $ext  = substr($path, $dot);

    $parts = [];
    foreach (UPLOAD_SIZES as $s) {
        $rel = $stem . '-' . $s . $ext;
        if (is_file(rtrim($SITE['upload_dir'], '/\\') . '/' . $rel)) {
            $parts[] = upload_url($rel) . ' ' . $s . 'w';
        }
    }
    return implode(', ', $parts);
}
